(function(){'use strict';
const KEY='nawaf-hq-v5';
const $=s=>document.querySelector(s);
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason='finance'){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function analyst(){const s=read();s.employees=Array.isArray(s.employees)?s.employees:[];let e=s.employees.find(x=>x.id==='finance');const profile={role:'المحلل المالي ونمو الأعمال',department:'المالية والنمو',mission:'تحليل الأسهم والشركات والقوائم المالية، ودراسة نماذج الربح والتسعير وتحقيق الدخل من مشاريع نواف. لا ينفذ شراء أو بيع أو تحويل أو صرف مالي دون الصلاحية والموافقة المناسبة.',permissions:{tasks:true,projects:true,review:true,code:false,deploy:false,external:true}};if(!e){e={id:'finance',name:'راكان',status:'READY',task:'',productivity:100,...profile};s.employees.push(e);write(s,'finance-analyst-created')}else{let changed=false;for(const [k,v] of Object.entries(profile)){if(JSON.stringify(e[k])!==JSON.stringify(v)){e[k]=v;changed=true}}if(changed)write(s,'finance-analyst-profile-updated')}return e}
function ensureModal(){let m=$('#finance-modal');if(m)return m;m=document.createElement('div');m.id='finance-modal';m.className='v9-modal';m.innerHTML='<div class="v9-dialog"><div id="finance-body"></div></div>';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-fin-close]'))m.classList.remove('show')});return m}
function open(){const e=analyst(),m=ensureModal();m.querySelector('#finance-body').innerHTML=`<div class="v9-dialog-head"><div><span>FINANCE & BUSINESS GROWTH</span><h2>${e.name} — المالية ونمو الأعمال</h2><p>تحليل استثماري + نماذج ربح وتسعير وتحقيق دخل من المشاريع. لا شراء أو بيع أو صرف تلقائي.</p></div><button data-fin-close>×</button></div><form id="finance-form" class="v9-form"><label>نوع التحليل<select name="workflow"><option value="stock">تحليل سهم</option><option value="compare">مقارنة شركات</option><option value="valuation">تقييم وقيمة عادلة</option><option value="earnings">تحليل نتائج وأرباح</option><option value="portfolio">مراجعة محفظة</option><option value="market">ملخص سوق وفرص ومخاطر</option><option value="business">نمو وربحية مشروع</option></select></label><label>السهم / الشركة / المشروع<input name="symbol" placeholder="مثال: 2222 أو AAPL أو قدّها"></label><label>الأفق<select name="horizon"><option value="long">طويل</option><option value="medium">متوسط</option><option value="short">قصير</option></select></label><label>المخاطر<select name="risk"><option value="balanced">متوازن</option><option value="conservative">محافظ</option><option value="aggressive">مرتفع</option></select></label><label class="v9-full">وش تبي تعرف؟<textarea name="question" rows="5" required placeholder="مثال: وش أفضل طرق نجيب دخل من قدّها بدون ما نخرب تجربة المستخدم؟"></textarea></label><div class="v9-full" style="padding:10px 12px;border:1px solid #ffffff14;border-radius:12px;color:#aeb8c8;font-size:12px;line-height:1.7">إذا الطلب عن سهم أو بيانات سوق: لازم يعتمد على مصدر حديث. إذا الطلب عن مشروع: يستخدم سياق المشروع ونموذج العمل ولا يختلق أرقام سوقية.</div><div class="v9-full v9-actions"><button type="button" data-fin-close>إلغاء</button><button class="primary" type="submit">ابدأ التحليل</button></div></form>`;m.classList.add('show');$('#finance-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),q=read(),emp=(q.employees||[]).find(x=>x.id==='finance')||analyst();const wf=String(f.get('workflow')||'stock'),symbol=String(f.get('symbol')||'').trim(),question=String(f.get('question')||'').trim(),horizon=String(f.get('horizon')||'long'),risk=String(f.get('risk')||'balanced');if(!question)return;const labels={stock:'تحليل سهم',compare:'مقارنة استثمارية',valuation:'تقييم مالي',earnings:'تحليل أرباح',portfolio:'مراجعة محفظة',market:'ملخص سوق',business:'نمو وربحية مشروع'};const details=`${labels[wf]||'تحليل مالي'}\nالأصل/الشركة/المشروع: ${symbol||'غير محدد'}\nالأفق: ${horizon}\nتحمل المخاطر: ${risk}\nالسؤال: ${question}\n\nقواعد إلزامية: افصل الحقائق عن الرأي، لا تختلق أرقاماً حالية، ولا تنفذ أي شراء أو بيع أو تحويل أو صرف أموال. في مهام المشاريع قدّم خيارات ربح وتجارب قابلة للقياس ولا تدّع وجود إيرادات لم يتم إثباتها.`;const projectId=/قدّها|قدها|qaddha/i.test(`${symbol} ${question}`)?'qaddha':/مُعِين|معين|mueen/i.test(`${symbol} ${question}`)?'mueen':'';const task={id:uid('t'),title:`${labels[wf]||'تحليل مالي'}: ${(symbol||question).slice(0,70)}`,details,employeeId:emp.id,projectId,status:'READY',progress:0,kind:'RESEARCH',priority:'HIGH',createdAt:new Date().toISOString(),createdBy:'NAWAF',domain:wf==='business'?'BUSINESS':'FINANCE'};q.tasks=Array.isArray(q.tasks)?q.tasks:[];q.tasks.unshift(task);emp.status='READY';emp.task=task.title;q.activity=Array.isArray(q.activity)?q.activity:[];q.activity.unshift({id:uid('a'),text:`تم تكليف ${emp.name}: ${task.title}`,type:'REAL',at:new Date().toISOString()});write(q,'finance-analysis-requested');m.classList.remove('show');setTimeout(()=>window.NawafAgents?.runTask?.(task.id).catch(()=>{}),160)}}
function inject(){analyst();if(document.querySelector('[data-finance-open]'))return;const strip=document.querySelector('.v9-control-strip');if(!strip)return;const b=document.createElement('button');b.type='button';b.setAttribute('data-finance-open','1');b.textContent='المالية والنمو';b.addEventListener('click',open);strip.appendChild(b)}
let t;const obs=new MutationObserver(()=>{clearTimeout(t);t=setTimeout(inject,100)});function boot(){obs.observe(document.body,{childList:true,subtree:true});inject()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.NawafFinance={open,analyst};
})();